import { __decorate } from "tslib";
import { Component } from '@angular/core';
import { FormGroup, FormControl } from '@angular/forms';
let AddStudentComponent = class AddStudentComponent {
    constructor(service, router, activatedRoute) {
        this.service = service;
        this.router = router;
        this.activatedRoute = activatedRoute;
    }
    async ngOnInit() {
        // this.studentData = this.service.student; 
        // this.service.student = undefined;
        // console.log(this.studentData);
        this.addStudent = new FormGroup({
            Name: new FormControl(''),
            Complete: new FormControl(false),
            Date: new FormControl(''),
        });
        // this.activatedRoute.queryParams.subscribe(params => {
        //   if (params) {
        //     this.studentId = params['studentId'];
        //   }
        // });
        // // console.log(this.studentId);
        // this.GetStudentById(this.studentId);
    }
    saveStudent() {
        this.service.addStudent(this.addStudent.value).subscribe(respose => {
            this.router.navigate(['Student']);
        });
        // });
    }
};
AddStudentComponent = __decorate([
    Component({
        selector: 'app-add-student',
        templateUrl: './add-student.component.html',
        styleUrls: ['./add-student.component.css']
    })
], AddStudentComponent);
export { AddStudentComponent };
